/**
 * Regenerates the error codes, webhook event names and payload types from Kirora's
 * OpenAPI spec:
 *
 *   pnpm codegen [path/to/openapi.json]
 *   pnpm codegen:check [path/to/openapi.json]
 *
 * By default the spec is downloaded from the commit of github.com/kiroratech/openapi
 * named in `spec/source.json`, and must match its `version` and `sha256`. A local path,
 * or KIRORA_OPENAPI_SPEC, is used instead without those checks, for trying out a spec
 * that isn't published yet. With `--check`, nothing is written: it exits with 1 if any
 * generated file is out of date.
 *
 * A download is cached in `node_modules/.cache/kirora-openapi`, under its checksum, so
 * later runs work offline.
 */
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import openapiTS, { astToString } from 'openapi-typescript';

const args = process.argv.slice(2);
const check = args.includes('--check');
const specArg = args.find((arg) => arg !== '--check') ?? process.env.KIRORA_OPENAPI_SPEC;
const source = JSON.parse(
  readFileSync(new URL('../spec/source.json', import.meta.url), 'utf8'),
);
const fail = (message) => {
  process.stderr.write(`${message}\n`);
  process.exit(1);
};

const cacheDir = new URL('../node_modules/.cache/kirora-openapi/', import.meta.url);
const cached = new URL(`${source.sha256}.json`, cacheDir);
const hash = (text) => createHash('sha256').update(text).digest('hex');

let specText;
if (specArg !== undefined) {
  specText = readFileSync(specArg, 'utf8');
} else if (existsSync(cached) && hash(readFileSync(cached, 'utf8')) === source.sha256) {
  specText = readFileSync(cached, 'utf8');
} else {
  const response = await fetch(source.url, { signal: AbortSignal.timeout(60_000) });
  if (!response.ok) fail(`Couldn't download ${source.url}: HTTP ${response.status}`);
  specText = await response.text();
}
const spec = JSON.parse(specText);
// Checked before generating, which is slow. A mismatch means source.json was only
// partly updated, so the record of what was generated from can't silently drift.
const sha256 = hash(specText);
if (
  specArg === undefined &&
  (source.sha256 !== sha256 || source.version !== spec.info.version)
) {
  fail(
    `${source.url} doesn't match spec/source.json. Set its version to ${spec.info.version} and its sha256 to ${sha256}.`,
  );
}
if (specArg === undefined && !existsSync(cached)) {
  mkdirSync(cacheDir, { recursive: true });
  writeFileSync(cached, specText);
}
const specName = specArg ?? source.url;
const errorCodes = spec.components.schemas.ErrorCode.enum;
const webhookEvents = Object.keys(spec.webhooks);
const header = '/** Generated by `pnpm codegen`. Do not edit. */';
const constList = (name, values) =>
  `${header}\nexport const ${name} = [\n${values.map((value) => `  '${value}',\n`).join('')}] as const;\n`;

/**
 * The operations a resource method wraps. Only these, the webhooks and what they
 * reference are generated, which keeps `models.ts` well under the whole API's size.
 * Add an operation here when you add its method.
 */
const OPERATIONS = [
  'listCampaigns',
  'getCampaign',
  'createCampaign',
  'sendCampaign',
  'triggerCampaign',
  'scheduleCampaign',
  'getCampaignEligibility',
  'listContacts',
  'getContact',
  'updateContact',
  'deleteContact',
  'identifyContact',
  'identifyContactsBatch',
  'deleteContacts',
  'mergeContacts',
  'getContactExport',
  'listContactLists',
  'listContactTopics',
  'setContactTopic',
  'listPushInstallations',
  'registerPushInstallation',
  'deletePushInstallation',
  'createEmbedSession',
  'getMe',
  'listMessages',
  'getMessage',
  'listSuppressions',
  'addSuppressions',
  'deleteSuppressions',
  'listWorkspaces',
  'createWorkspace',
  'getWorkspace',
  'updateWorkspace',
  'deleteWorkspace',
  'suspendWorkspace',
  'resumeWorkspace',
  'cancelWorkspaceDeletion',
  'trackEvent',
  'trackEventsBatch',
  'listLists',
  'getList',
  'createList',
  'updateList',
  'deleteList',
  'addListContacts',
  'deleteListContacts',
  'sendTransactionalMessage',
  'sendTransactionalMessagesBatch',
  'cancelScheduledTransactionalMessage',
];

/**
 * Removes the operations not in OPERATIONS, then every component nothing still uses. The
 * error codes and webhook names are read before this, from the whole spec.
 */
function prune(spec) {
  const found = new Set();
  for (const [path, item] of Object.entries(spec.paths)) {
    for (const [method, operation] of Object.entries(item)) {
      if (!operation?.operationId) continue;
      if (OPERATIONS.includes(operation.operationId)) found.add(operation.operationId);
      else delete item[method];
    }
    if (!Object.values(item).some((operation) => operation?.operationId)) {
      delete spec.paths[path];
    }
  }
  const missing = OPERATIONS.filter((operationId) => !found.has(operationId));
  if (missing.length > 0) fail(`Not in the spec: ${missing.join(', ')}`);

  const used = new Set();
  const visit = (value) => {
    if (Array.isArray(value)) return value.forEach(visit);
    if (typeof value !== 'object' || value === null) return;
    if (typeof value.$ref === 'string' && !used.has(value.$ref)) {
      used.add(value.$ref);
      const [, , kind, name] = value.$ref.split('/');
      visit(spec.components[kind][name]);
    }
    Object.values(value).forEach(visit);
  };
  visit(spec.paths);
  visit(spec.webhooks);
  // Also used by the client, which maps every error body onto it.
  visit({ $ref: '#/components/schemas/ErrorCode' });
  for (const [kind, components] of Object.entries(spec.components)) {
    for (const name of Object.keys(components)) {
      if (!used.has(`#/components/${kind}/${name}`)) delete components[name];
    }
  }
  return spec;
}

// Generate everything before writing anything, so a failure can't leave a mix of
// old and new files.
const models = astToString(await openapiTS(prune(spec), { defaultNonNullable: false }));
const outputs = new Map([
  ['../src/error-codes.ts', constList('ERROR_CODES', errorCodes)],
  ['../src/webhook-events.ts', constList('WEBHOOK_EVENTS', webhookEvents)],
  ['../src/models.ts', `${header}\n${models}`],
]);

if (check) {
  const stale = [...outputs]
    .filter(([path, content]) => {
      const url = new URL(path, import.meta.url);
      return !existsSync(url) || readFileSync(url, 'utf8') !== content;
    })
    .map(([path]) => path.replace('../', ''));
  if (stale.length > 0) {
    fail(`Out of date with ${specName}: ${stale.join(', ')}. Run \`pnpm codegen\`.`);
  }
  process.stdout.write('Generated files are up to date\n');
} else {
  for (const [path, content] of outputs) {
    writeFileSync(new URL(path, import.meta.url), content);
  }
  process.stdout.write(
    `Wrote ${errorCodes.length} error codes, ${webhookEvents.length} webhook events and the payload types\n`,
  );
}
